package com.kdroid.filter; import android.content.*; public class BootReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){if(Prefs.setup(c)){Policy.apply(c,Prefs.main(c)); Intent x=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(x);}}}